const http = require('http');
const WebSocket = require('ws');
const url = require('url');
const jwt = require('jsonwebtoken');
const Redis = require('ioredis');
const { Pool } = require('pg');

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const server = http.createServer();
const wss = new WebSocket.Server({ server });
const redisSub = new Redis(process.env.REDIS_URL);

wss.on('connection', (ws, req) => {
  const parsedUrl = url.parse(req.url, true);
  const token = parsedUrl.query.token;

  let decoded;
  try {
    decoded = jwt.verify(token, process.env.JWT_SECRET);
    ws.user = decoded;
  } catch (err) {
    ws.close(4001, 'Unauthorized');
    return;
  }

  ws.on('message', async (message) => {
    try {
      const data = JSON.parse(message);
      if (data.action === 'SUBSCRIBE_PORTFOLIO') {
        // Verify user has explicit access to portfolio in database
        const accessCheck = await pool.query(
          'SELECT 1 FROM portfolio_access WHERE portfolio_id = $1 AND user_id = $2',
          [data.portfolioId, ws.user.userId]
        );

        if (accessCheck.rowCount === 0) {
          ws.send(JSON.stringify({ error: 'Forbidden: unauthorized portfolio' }));
          return;
        }

        const channel = `portfolio:${data.portfolioId}:ticks`;
        redisSub.subscribe(channel);

        const onTick = (ch, msg) => {
          if (ch === channel) ws.send(msg);
        };
        redisSub.on('message', onTick);

        ws.on('close', () => {
          redisSub.removeListener('message', onTick);
        });
      }
    } catch (e) {
      ws.send(JSON.stringify({ error: 'Malformed payload' }));
    }
  });
});

server.listen(8001);
